input.command:
LOG=/tmp/t1-validation.log && : > "$LOG" && run(){ echo "=== CMD: $*" >> "$LOG"; "$@" >> "$LOG" 2>&1; echo "--- exit=$?" >> "$LOG"; }; 
printf 'The cat sat.\nThe cat ran!\nA dog.\n' > /tmp/sample.txt;
echo "=== 1) contract example (byte-exact)" >> "$LOG";
python -m wordstat /tmp/sample.txt > /tmp/out1.txt 2>/tmp/err1.txt; rc=$?; echo "exit=$rc" >> "$LOG"; echo "-- stdout od -c:" >> "$LOG"; od -c /tmp/out1.txt >> "$LOG"; echo "-- stderr bytes: $(wc -c < /tmp/err1.txt)" >> "$LOG"; od -c /tmp/err1.txt >> "$LOG";
echo "=== expected: lines: 3 / words: 8 / chars: 33 / top: cat=2 the=2 a=1" >> "$LOG";
cat -A /tmp/out1.txt >> "$LOG";
echo "=== 2) --json --top 2" >> "$LOG";
python -m wordstat --json --top 2 /tmp/sample.txt > /tmp/out2.txt 2>/tmp/err2.txt; rc=$?; echo "exit=$rc" >> "$LOG"; od -c /tmp/out2.txt >> "$LOG"; cat /tmp/out2.txt >> "$LOG";
echo "=== 3) --help" >> "$LOG";
python -m wordstat --help > /tmp/out3.txt 2>&1; echo "exit=$?" >> "$LOG"; cat /tmp/out3.txt >> "$LOG";
echo "=== 4) /nonexistent" >> "$LOG";
python -m wordstat /nonexistent > /tmp/out4.txt 2>/tmp/err4.txt; echo "exit=$?" >> "$LOG"; echo "stdout bytes=$(wc -c < /tmp/out4.txt)" >> "$LOG"; cat /tmp/err4.txt >> "$LOG";
echo "=== 5) no FILE" >> "$LOG";
python -m wordstat > /tmp/out5.txt 2>/tmp/err5.txt; echo "exit=$?" >> "$LOG"; echo "stdout bytes=$(wc -c < /tmp/out5.txt)" >> "$LOG"; echo "-- last stderr line:" >> "$LOG"; tail -1 /tmp/err5.txt >> "$LOG";
cat "$LOG"

LOG=/tmp/t1-validation2.log && : > "$LOG";
: > /tmp/empty.txt;
printf '\xff\xfe\x00bad' > /tmp/bad.bin;
echo "=== 6) empty file (od -c)" >> "$LOG";
python -m wordstat /tmp/empty.txt > /tmp/o6 2>/tmp/e6; echo "exit=$? stdout_bytes=$(wc -c < /tmp/o6) stderr_bytes=$(wc -c < /tmp/e6)" >> "$LOG"; od -c /tmp/o6 >> "$LOG";
echo "=== 6b) empty file --json" >> "$LOG";
python -m wordstat --json /tmp/empty.txt; echo "exit=$?" >> "$LOG";
echo "=== 7) directory" >> "$LOG";
python -m wordstat /tmp > /tmp/o7 2>/tmp/e7; echo "exit=$? stdout_bytes=$(wc -c < /tmp/o7)" >> "$LOG"; cat /tmp/e7 >> "$LOG";
echo "=== 8) invalid UTF-8" >> "$LOG";
python -m wordstat /tmp/bad.bin > /tmp/o8 2>/tmp/e8; echo "exit=$? stdout_bytes=$(wc -c < /tmp/o8)" >> "$LOG"; cat /tmp/e8 >> "$LOG";
echo "=== 9) usage errors --top 0 / --top -1 / --top abc / unknown flag / extra positional" >> "$LOG";
for a in "--top 0" "--top -1" "--top abc" "--bogus" "/tmp/sample.txt extra"; do
  python -m wordstat $a /tmp/sample.txt > /tmp/o9 2>/tmp/e9; rc=$?;
  echo "args='$a' exit=$rc stdout_bytes=$(wc -c < /tmp/o9) last_stderr='$(tail -1 /tmp/e9)'" >> "$LOG";
done;
echo "=== 9b) bare '--top 0' with no file + extra-positional separate form" >> "$LOG";
python -m wordstat --top 0 /tmp/sample.txt > /tmp/o9b 2>/tmp/e9b; echo "exit=$? last='$(tail -1 /tmp/e9b)'" >> "$LOG";
python -m wordstat /tmp/sample.txt extra > /tmp/o9c 2>/tmp/e9c; echo "exit=$? last='$(tail -1 /tmp/e9c)'" >> "$LOG";
echo "=== 10) --help goes to stdout only" >> "$LOG";
python -m wordstat --help > /tmp/o10 2>/tmp/e10; echo "exit=$? stdout_has_usage=$(grep -c '^usage: wordstat' /tmp/o10) stderr_bytes=$(wc -c < /tmp/e10)" >> "$LOG";
echo "=== 11) no traceback anywhere (grep Traceback in all stderr captured)" >> "$LOG";
grep -l Traceback /tmp/e6 /tmp/e7 /tmp/e8 /tmp/e9 /tmp/e9b /tmp/e9c 2>/dev/null || echo "no tracebacks" >> "$LOG";
cat "$LOG"

LOG=/tmp/t1-validation3.log && : > "$LOG";
echo "=== A) exact task command: printf ... | od -c | head -8" >> "$LOG";
printf 'The cat sat.\nThe cat ran!\nA dog.\n' > /tmp/sample.txt && python -m wordstat /tmp/sample.txt | od -c | head -8 >> "$LOG"; echo "pipeline exit=${PIPESTATUS[0]:-?}" >> "$LOG";
echo "=== B) task commands: --help; /nonexistent; no-args; --json" >> "$LOG";
python -m wordstat --help >/dev/null 2>&1; echo "help exit=$?" >> "$LOG";
python -m wordstat /nonexistent >/dev/null 2>&1; echo "missing exit=$?" >> "$LOG";
python -m wordstat >/dev/null 2>&1; echo "noargs exit=$?" >> "$LOG";
python -m wordstat --json /tmp/sample.txt >> "$LOG" 2>&1; echo "json exit=$?" >> "$LOG";
echo "=== C) CRLF chars (decision a: CRs count) + BOM strip" >> "$LOG";
printf 'a\r\n' > /tmp/crlf.txt; python -m wordstat /tmp/crlf.txt >> "$LOG" 2>&1;
printf '\xef\xbb\xbfHi\n' > /tmp/bom.txt; python -m wordstat /tmp/bom.txt >> "$LOG" 2>&1;
echo "=== D) ties: reverse-seen words (z=2,a=2 seen z first) and word-asc vs reverse trap" >> "$LOG";
printf 'z z a a\n' > /tmp/ties.txt; python -m wordstat --top 9 /tmp/ties.txt >> "$LOG" 2>&1;
echo "=== E) stdlib-only check: grep imports" >> "$LOG";
grep -n "^import\|^from" wordstat/*.py >> "$LOG";
echo "=== F) file listing" >> "$LOG";
ls -la wordstat/ >> "$LOG";
cat "$LOG"
